/// 运行期资源访问器：统一提供 Asset Catalog 取图 + 占位回退
enum AssetLibrary {
    /// 取图（找不到时返回 nil，由调用方决定占位策略）
    static func image(_ name: String) -> Image? {
        guard UIImage(named: name) != nil else { return nil }
        return Image(name)
    }

    /// 取 UIImage（用于需要原始像素的场景，如启动图、模糊背景）
    static func ui(_ name: String) -> UIImage? {
        UIImage(named: name)
    }

    /// 带占位的可缩放图片（AnyView 容器保证两侧类型一致）
    static func resizable(_ name: String,
                          contentMode: SwiftUI.ContentMode = .fill) -> some View {
        Group {
            if let img = image(name) {
                img.resizable().aspectRatio(contentMode: contentMode)
            } else {
                Rectangle()
                    .fill(Theme.bgCardHi)
                    .overlay(Image(systemName: "photo").foregroundStyle(Theme.textTertiary))
            }
        }
    }
}

